//   (parser.IsCompletePrefix branch):
//     CloseConstrainedSpan sets insideConstrainedOut := false; implication vacuous. ✓
//
//   (|currentConstrainedOut| >= maxSpanLength — span-cap branch):
//     CloseSpanWithinBudget postcondition: insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
//   (normal constrained step — token appended):
//     SafeRepetitionPenaltyStep hard-masks to parser-valid tokens plus EOS.
//     AppendConstrainedToken postcondition: parser.IsValidPrefix(currentOut). ✓
//
//   (EOS inside span — CloseSpanWithinBudget salvage):
//     CloseSpanWithinBudget postcondition: insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
//   (post-loop cleanup):
//     Same CloseSpanWithinBudget postcondition. ✓
//
